namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入0: x [M, K]
    // 输入1: weight [N, K]
    // 输入2: bias [N]
    // 输入3: constant [1] 或标量Tensor
    const auto* x_shape = context->GetInputShape(0);
    const auto* w_shape = context->GetInputShape(1);

    uint64_t m = 1;
    if (x_shape->GetOriginShape().GetDimNum() == 2) {
        m = x_shape->GetOriginShape().GetDim(0);
    } else {
        // 兜底：按最后一维为K，其余展平为M
        uint64_t total = x_shape->GetOriginShape().GetShapeSize();
        uint64_t k = x_shape->GetOriginShape().GetDim(x_shape->GetOriginShape().GetDimNum() - 1);
        m = total / k;
    }
    uint64_t k = x_shape->GetOriginShape().GetDim(x_shape->GetOriginShape().GetDimNum() - 1);
    uint64_t n = w_shape->GetOriginShape().GetDim(0); // weight: [N, K]

    MatmulMinSubtractCustomTilingData tiling;
    tiling.set_M(static_cast<uint32_t>(m));
    tiling.set_N(static_cast<uint32_t>(n));
    tiling.set_K(static_cast<uint32_t>(k));
    tiling.set_tileNum(TILE_NUM);

    context->SetBlockDim(BLOCK_DIM);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    workspaceSizes[0] = 0; // 本例不需要额外workspace
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);  // [M, K]
    const gert::Shape* w_shape = context->GetInputShape(1);  // [N, K]
    gert::Shape* y_shape = context->GetOutputShape(0);

    uint64_t m = 1;
    if (x_shape->GetOriginShape().GetDimNum() == 2) {
        m = x_shape->GetOriginShape().GetDim(0);
    } else {
        uint64_t total = x_shape->GetOriginShape().GetShapeSize();
        uint64_t k = x_shape->GetOriginShape().GetDim(x_shape->GetOriginShape().GetDimNum() - 1);
        m = total / k;
    }
    uint64_t n = w_shape->GetOriginShape().GetDim(0);

    gert::Shape out_origin({(int64_t)m, (int64_t)n});
    *y_shape = gert::Shape(out_origin);
    return GRAPH_SUCCESS;
}

