at::Tensor matmul_min_subtract_custom_impl_npu(const at::Tensor& x,
                                               const at::Tensor& weight,
                                               const at::Tensor& bias,
                                               const at::Tensor& constant) {
    // 输出形状 [M, N]
    at::IntArrayRef x_sizes = x.sizes();
    TORCH_CHECK(x_sizes.size() == 2, "x must be 2D");
    int64_t M = x_sizes[0];
    int64_t N = weight.size(0);
    at::Tensor y = at::empty({M, N}, x.options());
    EXEC_NPU_CMD(aclnnMatmulMinSubtractCustom, x, weight, bias, constant, y);
    return y;
}

